def revenue_by_customer(rows):
    """Sum each customer's revenue, per currency, in Decimal major units.

    Returns {customer_id: {currency: Decimal}}, each total quantized to 4 places.
    """
    totals = {}
    for row in rows:
        by_currency = totals.setdefault(row["customer_id"], {})
        currency = row["currency"]
        amount = Decimal(row["total_cents"]) / 100
        by_currency[currency] = by_currency.get(currency, Decimal(0)) + amount
    return {
        customer_id: {
            currency: total.quantize(Decimal("0.0001"))
            for currency, total in by_currency.items()
        }
        for customer_id, by_currency in totals.items()
    }

